from . import fast_scalper_beta_001_legacy as legacy
from fastapi import HTTPException

app=legacy.app
S=legacy.S; B=legacy.B; START=legacy.START; N=legacy.MAX_SLOTS

async def mode_fixed(b: legacy.Mode):
    m=b.mode.upper()
    if m not in {'PAPER','BINANCE_TEST'}:
        raise HTTPException(403,'Unsupported mode')
    if S['running'] or S['positions']:
        raise HTTPException(400,'BOT OFF and no open positions required')
    S['mode']=m; S['bot']=0.0; S['free']=0.0; S['error']=None
    if m=='PAPER':
        S['account']=START; S['reserve']=START
    else:
        S['account']=0.0; S['reserve']=0.0
        try:
            await B.ping(); a=await B.account(); u=next((float(x['free']) for x in a.get('balances',[]) if x.get('asset')=='USDT'),0.0)
            S['account']=u; S['reserve']=u
        except Exception as e:
            S['error']=f'Binance TEST: {e}'
    return await legacy.state()

for r in app.router.routes:
    if getattr(r,'path',None)=='/api/mode' and getattr(r,'methods',None):
        r.endpoint=mode_fixed
        if hasattr(r,'dependant'): r.dependant.call=mode_fixed

legacy.HTML="""<!doctype html><html><head><meta name='viewport' content='width=device-width,initial-scale=1'><title>Fast Scalper Beta</title><style>*{box-sizing:border-box}body{margin:0;background:#080e1b;color:#eef3ff;font-family:system-ui}.w{max-width:900px;margin:auto;padding:14px}.title{font-size:30px;font-weight:900}.muted{color:#8b97ae}.card{background:#121a2c;border:1px solid #293650;border-radius:16px;padding:14px;margin:10px 0}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.stat{background:#0d1425;border-radius:10px;padding:10px}.v{font-size:19px;font-weight:850}.row{display:flex;gap:8px;flex-wrap:wrap}.input,.select,.slot{background:#0b1322;color:#fff;border:1px solid #30405f;border-radius:9px;padding:10px;flex:1;min-width:120px}.btn{border:0;border-radius:10px;padding:11px 15px;color:#fff;font-weight:850;background:#273650}.on{background:#078b53}.stop{background:#a72e3f}.test{background:#183b66}.grid6{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.rank{display:grid;grid-template-columns:22px 1fr 65px 50px;gap:5px;padding:5px;border-bottom:1px solid #24314a;font-size:9px}.line{font-size:12px;padding:4px 0;border-bottom:1px solid #24314a}@media(max-width:650px){.stats{grid-template-columns:repeat(2,1fr)}.grid6{grid-template-columns:repeat(2,1fr)}}</style></head><body><div class=w><div class=title>⚡ Fast Scalper Beta</div><div class=muted>Version 0.01 REPAIR PAPER · Trading TF: 3m</div><div class=card><div class=stats><div class=stat>Account Balance<div class=v id=account>—</div></div><div class=stat>Bot Balance<div class=v id=bot>—</div></div><div class=stat>Reserve<div class=v id=reserve>—</div></div><div class=stat>Session PnL<div class=v id=sp>—</div></div></div><div class=row style='margin-top:10px'><select id=modeSel class=select><option>PAPER</option><option>BINANCE_TEST</option></select><button class='btn test' id=modeBtn>SET MODE</button><button class='btn test' id=testBtn>TEST BINANCE</button></div></div><div class=card><div class=row><input id=allocation class=input type=number step=.01 min=0 placeholder='Bot Allocation, USDT'><button class='btn test' id=allocBtn>SET BOT BALANCE</button><input id=profit class=input type=number step=.01 value=.41><label style='padding:10px'><input id=reinvest type=checkbox checked> Reinvest</label></div><div class=row style='margin-top:8px'><button class='btn on' id=onBtn>BOT ON · ACTIVE</button><button class='btn stop' id=emBtn>EMERGENCY</button><button class=btn id=resetBtn>RESET</button><button class='btn stop' id=offBtn>BOT OFF</button><span class=muted id=tim>SESSION 00:00 · 24H 00:00</span></div></div><div class=card><h2>Slots · TOP-6</h2><div class=grid6 id=slots></div><div class=row style='margin-top:10px'><button class='btn on' id=pairsBtn>SET PAIRS</button><button class=btn id=addBtn>＋ ADD PAIR</button><button class=btn id=topBtn>AUTO TOP-6</button></div></div><div class=card><details open><summary>Radar · TOP-15 · recommended pairs</summary><div id=radar></div></details></div><div class=card><h2>Open Positions</h2><div id=pos class=muted>No open positions</div></div><div class=card><h2>Closed Trades — latest 5</h2><div id=closed class=muted>No closed trades</div></div></div><script>
let s={},ready=false;const $=id=>document.getElementById(id),P=()=>$('profit').value*1||0,R=()=>$('reinvest').checked;async function api(u,m='GET',b){let r=await fetch(u,{method:m,headers:{'Content-Type':'application/json'},body:b?JSON.stringify(b):undefined}),j=await r.json();if(!r.ok)throw Error(j.detail||JSON.stringify(j));return j}function draw(force=false){if(ready&&!force)return;let a=s.slots||[];$('slots').innerHTML=Array.from({length:6},(_,i)=>`<input class=slot id=s${i} placeholder='USDT pair' value='${a[i]||''}'>`).join('');ready=true}function sync(){for(let i=0;i<6;i++){let e=$('s'+i);if(e)e.value=(s.slots||[])[i]||''}}function f(x){return (+x||0).toFixed(4)}function clock(x){x=Math.floor(x||0);return String(Math.floor(x/60)).padStart(2,'0')+':'+String(x%60).padStart(2,'0')}function render(){$('modeSel').value=s.mode;$('account').textContent=f(s.account);$('bot').textContent=f(s.bot_balance);$('reserve').textContent=f(s.reserve);$('sp').textContent=f(s.session_realized);$('tim').textContent='SESSION '+clock(s.session_age)+' · 24H '+clock(s.day_age);let p=s.positions||[];$('pos').innerHTML=p.map(x=>`<div class=line>${x.symbol} · ${f(x.stake)} USDT · ${f(x.current)}</div>`).join('')||'No open positions';$('closed').innerHTML=(s.closed||[]).slice(0,5).map(x=>`<div class=line>${x.symbol} · ${x.reason} · ${f(x.pnl)} USDT · ${f(x.exit)}</div>`).join('')||'No closed trades';$('radar').innerHTML=(s.ranking||[]).map((x,i)=>`<div class=rank><b>${i+1}</b><b>${x.symbol}</b><span>${f(x.price)}</span><span>${f(x.score)}</span></div>`).join('')}
async function load(){try{let first=!ready,old=s.mode;s=await api('/api/state');if(first||old!==s.mode)draw(true);render()}catch(e){}}async function setMode(){try{s=await api('/api/mode','POST',{mode:$('modeSel').value});render()}catch(e){alert(e.message)}}async function test(){try{await api('/api/binance/test','POST')}catch(e){alert(e.message)}}async function alloc(){try{s=await api('/api/allocation','POST',{amount:+$('allocation').value});render()}catch(e){alert(e.message)}}async function on(){try{s=await api('/api/paper/start','POST',{profit_pct:P(),reinvest:R()});render()}catch(e){alert(e.message)}}async function off(){try{s=await api('/api/paper/stop','POST');render()}catch(e){alert(e.message)}}async function emergency(){try{s=await api('/api/paper/emergency','POST');render()}catch(e){alert(e.message)}}async function reset(){try{s=await api('/api/reset','POST');render();sync()}catch(e){alert(e.message)}}async function pairs(){try{s=await api('/api/slots','POST',{slots:Array.from({length:6},(_,i)=>$('s'+i).value).filter(Boolean),profit_pct:P(),reinvest:R()});sync();render()}catch(e){alert(e.message)}}async function top(){try{s=await api('/api/slots/auto-top6','POST',{slots:[],profit_pct:P(),reinvest:R()});sync();render()}catch(e){alert(e.message)}}function add(){for(let i=0;i<6;i++){let e=$('s'+i);if(e&&!e.value.trim()){e.focus();return}}}$('modeBtn').onclick=setMode;$('testBtn').onclick=test;$('allocBtn').onclick=alloc;$('onBtn').onclick=on;$('offBtn').onclick=off;$('emBtn').onclick=emergency;$('resetBtn').onclick=reset;$('pairsBtn').onclick=pairs;$('topBtn').onclick=top;$('addBtn').onclick=add;draw();load();setInterval(load,1000);
</script></body></html>"""